constexpr const char* radial_gradient_frag_src = R"(#version 450

layout(location = 0) in vec2 v_TexCoord;
layout(location = 1) in vec4 v_Color;

layout(location = 0) out vec4 FragColor;

layout(push_constant) uniform PushConstants {
    mat4 u_ViewProjection;
    mat4 u_Model;
    vec4 u_TintColor;
} pc;

layout(set = 0, binding = 2) uniform MaterialData {
    bool u_UseTexture;
    vec4 u_GradientParams;
    vec2 u_Size;
    vec4 u_UVRect;
} material;

layout(set = 0, binding = 4) uniform sampler2D u_Texture;


    void main() {
        // material.u_GradientParams.x = falloff exponent, .y = inner radius (0..1 fraction)
        float falloff = max(material.u_GradientParams.x, 0.0001);
        float innerRadius = clamp(material.u_GradientParams.y, 0.0, 0.999);

        // Distance from the quad centre (TexCoord 0.5), normalised so the quad
        // edge midpoint maps to 1.0 and the centre to 0.0.
        float dist = clamp(length(v_TexCoord - vec2(0.5)) * 2.0, 0.0, 1.0);

        // Remap past the inner radius, then apply the falloff curve.
        float t = clamp((dist - innerRadius) / max(1.0 - innerRadius, 0.0001), 0.0, 1.0);
        float atten = pow(1.0 - t, falloff);

        vec4 color = v_Color * pc.u_TintColor;

        if (material.u_UseTexture) {
            vec2 uvMin = material.u_UVRect.xy;
            vec2 uvMax = material.u_UVRect.zw;
            vec2 remappedUV = uvMin + (v_TexCoord * (uvMax - uvMin));
            color *= texture(u_Texture, remappedUV);
        }

        color.a *= atten;

        if (color.a < 0.001) {
            discard;
        }

        FragColor = color;
    }
)";

