    // uniforms.u_ToonMaterialParams: x=shadowBands, y=specularBands, z=normalScale, w=emissiveStrength
    float shadowBands = max(uniforms.u_ToonMaterialParams.x, 2.0);
    float specularBands = max(uniforms.u_ToonMaterialParams.y, 2.0);
    float normalScale = uniforms.u_ToonMaterialParams.z;
