// Original HLSL source (for debugging)
constexpr const char* radial_gradient_frag_src = R"(
// DirectX12 RadialGradient Fragment Shader

cbuffer PushConstants : register(b0)
{
    float4x4 u_ViewProjection;
    float4x4 u_Model;
    float4x4 u_NormalMatrix;
    float4 u_TintColor;
    int u_UseTexture;
    float u_AlphaCutoff;
    float _pad1;
    float _pad2;
    float4 u_UVRect;
    float4 u_GradientParams;
    float2 u_Size;
    float2 _padSize;
    float4 u_MaterialParams2;
    float4 u_CameraPosition;
    float4 u_AlbedoColor;
    float4 u_EmissiveColor;
    int u_ReceiveShadow;
    float _pad3;
    float _pad4;
    float _pad5;
};

Texture2D u_Texture : register(t0);
SamplerState u_Texture_sampler : register(s0);

struct PS_INPUT
{
    float4 position : SV_POSITION;
    float2 v_TexCoord : TEXCOORD0;
    float4 v_Color : TEXCOORD1;
};

float4 main(PS_INPUT input) : SV_TARGET
{
    float4 FragColor;

    // u_GradientParams.x = falloff exponent, .y = inner radius (0..1 fraction)
    float falloff = max(u_GradientParams.x, 0.0001);
    float innerRadius = clamp(u_GradientParams.y, 0.0, 0.999);
    // Distance from the quad centre (TexCoord 0.5), normalised so the quad
    // edge midpoint maps to 1.0 and the centre to 0.0.
    float dist = clamp(length(input.v_TexCoord - float2(0.5, 0.5)) * 2.0, 0.0, 1.0);
    // Remap past the inner radius, then apply the falloff curve.
    float t = clamp((dist - innerRadius) / max(1.0 - innerRadius, 0.0001), 0.0, 1.0);
    float atten = pow(1.0 - t, falloff);
    float4 color = input.v_Color * u_TintColor;
    if (u_UseTexture) {
    float2 uvMin = u_UVRect.xy;
    float2 uvMax = u_UVRect.zw;
    float2 remappedUV = uvMin + (input.v_TexCoord * (uvMax - uvMin));
    color *= u_Texture.Sample(u_Texture_sampler, remappedUV);
    }
    color.a *= atten;
    if (color.a < 0.001) {
    discard;
    }
    FragColor = color;

    return FragColor;
}

)";
