    output.v_TexCoord = input.a_TexCoord;
    output.v_Color = input.a_Color;
    output.v_LocalPos = input.a_Position.xy;
    output.position = mul(u_ViewProjection, mul(u_Model, float4(input.a_Position, 1.0)));

